/**
 * Cloudinary Media Upload Controller.
 * 
 * Handles uploading saree model pictures to Cloudinary CDN
 * and deleting removed or replaced images.
 */

const { cloudinary } = require('../config/cloudinary');

/**
 * Handle multipart image upload to Cloudinary.
 * POST /v1/upload
 */
function uploadImage(req, res) {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No image provided' });
    }

    // req.file.path contains the secure HTTPS CDN URL generated by Cloudinary
    return res.status(200).json({ imageUrl: req.file.path });
  } catch (err) {
    return res.status(500).json({ error: 'Error uploading to Cloudinary: ' + err.message });
  }
}

/**
 * Delete an image asset from Cloudinary by its CDN URL.
 * POST /v1/delete-image
 */
async function deleteImage(req, res, next) {
  try {
    const { imageUrl } = req.body;
    if (!imageUrl) {
      return res.status(400).json({ error: 'No image URL provided' });
    }

    // Extract public ID relative to the 'tally-app' folder
    const parts = imageUrl.split('/');
    const folderIndex = parts.indexOf('tally-app');

    if (folderIndex !== -1) {
      const publicIdWithExt = parts.slice(folderIndex).join('/');
      const publicId = publicIdWithExt.substring(0, publicIdWithExt.lastIndexOf('.'));
      
      console.log(`🗑️ Deleting asset from Cloudinary: ${publicId}`);
      await cloudinary.uploader.destroy(publicId);
    }

    return res.status(200).send();
  } catch (err) {
    next(err);
  }
}

module.exports = {
  uploadImage,
  deleteImage,
};
